#!/bin/bash
# tests/cost-grok-usage.bh-1636-test.sh — grok output tokens include reasoning.
#
# THE GAP (BH-1636 item 3). The one measured 1.0.40 envelope carries
# `usage.output_tokens 1` beside `usage.reasoning_tokens 412`. One output token
# cannot contain 412 reasoning tokens, so grok reports them SEPARATELY, and a
# cost row that says output_toks=1 under-reports what the call generated by
# 412. bin/grok-usage.sh now adds a reasoning count to the output count when it
# is a SIBLING of the output key in the same usage dict — and only then:
#
#   * OpenAI's nested `output_tokens_details.reasoning_tokens` is already
#     INSIDE output_tokens, so adding it would double count (R3a);
#   * codex's `reasoning_output_tokens` is not grok's key and is not read (R3b);
#   * a negative, non-numeric or null reasoning value is absent, not zero and
#     not added (R3c);
#   * reasoning alone never makes a dict a usage record (R3d).
#
# Dollars do not move: the envelope's vendor total still wins (R1, R4).
#
# Run from anywhere: HARNESS_TEST_SANDBOX=1 bash tests/cost-grok-usage.bh-1636-test.sh
set -uo pipefail
. "$(dirname "$0")/lib/scratch.sh" || exit 1
DIR=$(cd "$(dirname "$0")/.." && pwd)
. "$DIR/tests/lib/model-route-stub.sh" || exit 1
mrs_fixture "$T" testproj
GU="$DIR/bin/grok-usage.sh"
ENV_FIX="$DIR/tests/fixtures/grok-usage/1.0.40/envelope.json"
mkdir -p "$T/logs" "$T/flags" "$T/locks" "$T/fakebin" "$T/bin" "$T/env"
: > "$T/env/global.env"
PASS=0; FAIL=0
ok()  { PASS=$((PASS+1)); }
bad() { FAIL=$((FAIL+1)); echo "FAIL: $1"; }

# walk_one <json line> — the summary for a grok home holding just that line.
N=0
walk_one() {
  N=$((N+1)); mkdir -p "$T/gh$N"
  printf '%s\n' "$1" > "$T/gh$N/unified.jsonl"
  bash "$GU" 0 "$T/gh$N"
}

# ── R1. the envelope: 1 output + 412 reasoning = 413, dollars unchanged ──────
echo "--- R1. envelope"
OUT=$(bash "$GU" --envelope "$ENV_FIX" 0 "$T/none"); RC=$?
[ "$RC" = 0 ] && ok || bad "R1 the reader must never fail the caller (rc=$RC)"
[ "$OUT" = "57398 413 1152 0 0.117850" ] && ok \
  || bad "R1 the 1.0.40 envelope: expected '57398 413 1152 0 0.117850', got '$OUT'"

# ── R2. the walk path counts a sibling reasoning key too ─────────────────────
echo "--- R2. walk"
OUT=$(walk_one '{"usage":{"input_tokens":100,"output_tokens":5,"reasoning_tokens":7}}')
[ "$OUT" = "100 12   " ] && ok || bad "R2 walk: expected '100 12   ', got '$OUT'"
OUT=$(walk_one '{"usage":{"inputTokens":100,"outputTokens":5,"reasoningTokens":7}}')
[ "$OUT" = "100 12   " ] && ok || bad "R2 walk (camelCase): expected '100 12   ', got '$OUT'"

# ── R3. the negatives: nothing is added that is not grok's sibling count ─────
echo "--- R3. negatives"
OUT=$(walk_one '{"usage":{"input_tokens":100,"output_tokens":50,"output_tokens_details":{"reasoning_tokens":40}}}')
[ "$OUT" = "100 50   " ] && ok || bad "R3a nested output_tokens_details.reasoning_tokens must NOT be added: got '$OUT'"
OUT=$(walk_one '{"usage":{"input_tokens":100,"output_tokens":50,"reasoning_output_tokens":40}}')
[ "$OUT" = "100 50   " ] && ok || bad "R3b codex reasoning_output_tokens must NOT be added: got '$OUT'"
for v in -3 '"abc"' null; do
  OUT=$(walk_one "{\"usage\":{\"input_tokens\":100,\"output_tokens\":50,\"reasoning_tokens\":$v}}")
  [ "$OUT" = "100 50   " ] && ok || bad "R3c reasoning_tokens=$v must be absent, not added: got '$OUT'"
done
# The envelope path takes the same guard: a bad reasoning value leaves output.
printf '%s\n' '{"usage":{"input_tokens":10,"output_tokens":4,"reasoning_tokens":"abc"},"total_cost_usd":0.5}' > "$T/badenv.json"
OUT=$(bash "$GU" --envelope "$T/badenv.json" 0 "$T/none")
[ "$OUT" = "10 4   0.500000" ] && ok || bad "R3c envelope with a non-numeric reasoning count: got '$OUT'"
OUT=$(walk_one '{"usage":{"input_tokens":100,"reasoning_tokens":40}}')
[ "$OUT" = "    " ] && ok || bad "R3d reasoning with no output key must not become a usage row: got '$OUT'"
printf '%s\n' '{"usage":{"input_tokens":5,"reasoning_tokens":9},"total_cost_usd":9.99}' > "$T/halfenv.json"
OUT=$(bash "$GU" --envelope "$T/halfenv.json" 0 "$T/none")
[ "$OUT" = "    " ] && ok || bad "R3d an envelope with reasoning but no output key must fall through, not price: got '$OUT'"
OUT=$(walk_one '{"modelUsage":{"grok-4.7":{"inputTokens":57398,"outputTokens":1,"cacheReadInputTokens":1152,"cacheCreationInputTokens":0,"modelCalls":1,"costUSD":0.11785}}}')
[ "$OUT" = "57398 1 1152 0 0.117850" ] && ok || bad "R3e modelUsage with no reasoning key stays at output 1: got '$OUT'"

# ── R5. the cliff series: input and cache_read never move ────────────────────
echo "--- R5. --calls"
mkdir -p "$T/cl1" "$T/cl2"
printf '%s\n' '{"usage":{"inputTokens":100,"outputTokens":5,"reasoning_tokens":7,"cachedReadTokens":10}}' \
              '{"usage":{"inputTokens":300,"outputTokens":9,"reasoning_tokens":30,"cachedReadTokens":20}}' > "$T/cl1/u.jsonl"
printf '%s\n' '{"usage":{"inputTokens":100,"outputTokens":5,"cachedReadTokens":10}}' \
              '{"usage":{"inputTokens":300,"outputTokens":9,"cachedReadTokens":20}}' > "$T/cl2/u.jsonl"
A=$(bash "$GU" --calls 0 "$T/cl1" | awk '{print $1, $2, $4}')
B=$(bash "$GU" --calls 0 "$T/cl2" | awk '{print $1, $2, $4}')
[ -n "$A" ] && [ "$A" = "$B" ] && ok || bad "R5 --calls cols 1/2/4 must not change with reasoning keys: '$A' vs '$B'"
[ "$(bash "$GU" --calls 0 "$T/cl1" | tail -1)" = "2 300 39 20 " ] && ok \
  || bad "R5 the series output column counts reasoning: '$(bash "$GU" --calls 0 "$T/cl1" | tail -1)'"

# ── R4. the production entry point: bin/agent-call.sh prices 413 ─────────────
echo "--- R4. bin/agent-call.sh (driven)"
mkdir -p "$T/.grok/bin"
cat > "$T/.grok/bin/grok" <<'EOF'
#!/bin/bash
for a in "$@"; do
  if [ "$a" = json ]; then cat "$GROK_ENVELOPE"; exit 0; fi
done
echo "DECISION: BH-1636 :: skip :: fake"
EOF
chmod +x "$T/.grok/bin/grok"
printf '#!/bin/bash\necho subscription\n' > "$T/fakebin/billing-mode.sh"; chmod +x "$T/fakebin/billing-mode.sh"
cat > "$T/fakebin/timeout" <<'EOF'
#!/bin/bash
[ "${1:-}" = "--kill-after" ] && shift 2
case "${1:-}" in --kill-after=*) shift ;; esac
shift
exec "$@"
EOF
chmod +x "$T/fakebin/timeout"
cat > "$T/prices.json" <<'EOF'
{"per_token": {
  "grok-4.6": {"prompt": 0.000002, "completion": 0.000006, "cache_read": 5e-7, "cache_write": null}
}}
EOF
rm -f "$T/logs/cost.csv"
# Same key fence as bh-1494 §D: an unfenced run could reach a real vendor.
( unset OPENROUTER_API_KEY FIREWORKS_API_KEY XAI_API_KEY GROK_CODE_XAI_API_KEY \
        OPENAI_API_KEY CODEX_API_KEY GEMINI_API_KEY ANTHROPIC_API_KEY HARNESS_SECRET
  export HOME="$T" HARNESS="$T" PATH="$T/fakebin:$PATH" \
         MODEL_PRICES="$T/prices.json" \
         CONTEXT_BUDGETS="$DIR/catalog/context-budgets.json" \
         GROK_ENVELOPE="$ENV_FIX" GROK_OUTPUT_JSON=1 \
         RUNNER_TRIAGE=grok RUNNER_TRIAGE_FALLBACK=grok
  bash "$DIR/bin/agent-call.sh" triage testproj grok-4.6 60 "$T/out.txt" "hello" >/dev/null 2>&1 )
RC=$?
[ "$RC" = 0 ] && ok || bad "R4 the driven call failed (rc=$RC)"
col() { tail -1 "$T/logs/cost.csv" 2>/dev/null | awk -F, -v c="$1" '{print $c}'; }
[ "$(col 10)" = 413 ] && ok || bad "R4 output_toks (col 10) must count reasoning: got '$(col 10)'"
[ "$(col 13)" = 0.117850 ] && ok || bad "R4 cost_usd (col 13) must stay the vendor total: got '$(col 13)'"
[ "$(col 18)" = ledger ] && ok || bad "R4 row_source (col 18): got '$(col 18)'"

echo "cost-grok-usage.bh-1636-test: $PASS pass, $FAIL fail"
[ "$FAIL" -eq 0 ]
